    void analyzeVideo(android.net.Uri uri){
        toast("正在本机抽取视频画面…");String question=prefs().getString("videoQuestion","概括视频画面");
        io.submit(()->{File temporary=null;try{
            JSONObject sample;
            try{sample=VideoFrames.local(this,uri);}catch(Exception nativeFailure){
                File directory=new File(getFilesDir(),"linux/rootfs/opt/qq-workbench/video-imports");
                if(!new File(getFilesDir(),"linux/rootfs/opt/qq-workbench").isDirectory())throw new IOException("请先等待本地环境启动完成");
                if(!directory.isDirectory()&&!directory.mkdirs())throw new IOException("视频暂存目录无法创建");
                temporary=new File(directory,"clip-"+java.util.UUID.randomUUID().toString().replace("-","")+".bin");
                try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("无法打开视频");VideoFrames.copy(in,temporary);}
                sample=new JSONObject().put("clip",temporary.getName());
            }
            sample.put("question",question);JSONObject result=api("/video/analyze",sample);
            runOnUiThread(()->{if(!destroyed)new AlertDialog.Builder(this).setTitle(result.optBoolean("ok")?"视频画面分析":"视频暂不可用").setMessage(result.optString("message")+"\n\n"+result.optString("answer")).setPositiveButton("知道了",null).show();});
        }catch(Exception e){runOnUiThread(()->toast("视频读取失败："+e.getMessage()));}finally{if(temporary!=null)temporary.delete();}});
    }

